{
 "name": "stack-juguete",
 "description": "paquete de juguete con las condiciones de los revisores de React y Next de un paquete de stack",
 "agents": "agents",
 "reviewers": [
  {
   "agent": "rev-next-juguete",
   "group": "base",
   "when": {
    "all": [
     {
      "detection": "hasNext"
     },
     {
      "any": [
       {
        "detection": "tsxModified"
       },
       {
        "all": [
         {
          "detection": "depChanged"
         },
         {
          "no": {
           "detection": "csModified"
          }
         }
        ]
       }
      ]
     }
    ]
   },
   "surface": {
    "paths": [
     "**/*.tsx",
     "**/*.ts"
    ]
   },
   "depth": "standard",
   "prefixes": [
    "NEXTJ"
   ]
  },
  {
   "agent": "rev-react-juguete",
   "group": "base",
   "when": {
    "all": [
     {
      "detection": "hasReact"
     },
     {
      "no": {
       "detection": "hasNext"
      }
     },
     {
      "any": [
       {
        "detection": "tsxModified"
       },
       {
        "all": [
         {
          "detection": "depChanged"
         },
         {
          "no": {
           "detection": "csModified"
          }
         }
        ]
       }
      ]
     }
    ]
   },
   "surface": {
    "paths": [
     "**/*.tsx",
     "**/*.ts",
     "**/*.jsx",
     "**/*.js"
    ]
   },
   "depth": "standard",
   "prefixes": [
    "REACTJ"
   ]
  }
 ]
}

